implementation:
#include <cmath>

namespace APE {

class Properties {
public:
    int totalFrames;
    int compressionLevel;
    int channels;
    int sampleRate;
    int blocksPerFrame;
    int totalBlocks;
    double audioLengthSeconds;
    int bitrateKbps;
    int streamLength;
};

void analyzeOld(Properties& properties) {
    // Assume data is read from the APE file header
    // For the purpose of this example, we will use dummy values
    // In a real implementation, this data would be read from the file

    // Extract properties from the header
    int version = 1; // Example version
    properties.totalFrames = 1000; // Example total frames
    properties.compressionLevel = 5; // Example compression level
    properties.channels = 2; // Example channels
    properties.sampleRate = 44100; // Example sample rate
    properties.streamLength = 1024; // Example stream length

    // Calculate blocks per frame based on version and compression level
    if (version == 1) {
        if (properties.compressionLevel <= 4) {
            properties.blocksPerFrame = 1024;
        } else {
            properties.blocksPerFrame = 512;
        }
    } else {
        properties.blocksPerFrame = 1024; // Default for other versions
    }

    // Calculate total blocks
    properties.totalBlocks = properties.totalFrames * properties.blocksPerFrame;

    // Calculate audio length in seconds
    properties.audioLengthSeconds = static_cast<double>(properties.totalBlocks) / properties.sampleRate;

    // Calculate bitrate in kbps
    if (properties.totalBlocks > 0) {
        properties.bitrateKbps = static_cast<int>(
            (static_cast<double>(properties.streamLength) * 8.0) / properties.audioLengthSeconds / 1000.0
        );
    } else {
        properties.bitrateKbps = 0;
    }
}

} // namespace APE
